/** 与 Figma Make 参考站 http://localhost:8443/ 逐像素对齐的 UI 模式（test 构建开启） */
export function isRef8443(): boolean {
  const flag = (import.meta.env.VITE_UI_REF8443 as string | undefined) ?? ''
  return flag === 'true' || flag === '1'
}

/* 8443 参考站样式 — 仅在 .ui-ref8443 下生效 */
.ui-ref8443.screen{background:#f2f4f8;font-family:'Noto Sans SC:Regular','Noto Sans SC',sans-serif;font-size:14px;padding:calc(var(--status-bar-height,0px)) 0 calc(72px + env(safe-area-inset-bottom))}
.ui-ref8443 .app-header{position:sticky;top:var(--status-bar-height,0px);z-index:30;height:56px;display:grid;grid-template-columns:48px 1fr 48px;align-items:center;background:rgba(247,249,253,.96);backdrop-filter:blur(12px);border-bottom:1px solid #eceef2;box-shadow:none;max-width:none}
.ui-ref8443 .app-header-title{grid-column:2;font-family:'Noto Sans SC:Medium','Noto Sans SC',sans-serif;font-size:18px;font-weight:500;line-height:1.2}
.ui-ref8443 .app-back{grid-column:1;position:static;left:auto;height:56px;width:48px;justify-content:center}
.ui-ref8443 .app-back-glyph{font-family:Arial,sans-serif;font-size:34px;transform:translateY(-2px)}
.ui-ref8443 .ref8443-page{width:min(100%,760px);margin:0 auto;padding:10px 16px 110px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}
.ui-ref8443 .card,.ui-ref8443 .work-card{background:#fff;border-radius:12px;padding:16px;box-shadow:0 1px 2px rgba(28,36,51,.06)}
.ui-ref8443 .form-page,.ui-ref8443 .card.fields{display:flex;flex-direction:column;gap:12px}
.ui-ref8443 .fields{display:flex;flex-direction:column;gap:14px}
.ui-ref8443 .field-block{display:flex;flex-direction:column;gap:5px}
.ui-ref8443 .field-block-label{font-family:'Noto Sans SC:Medium','Noto Sans SC',sans-serif;font-size:14px;font-weight:500}
.ui-ref8443 .required .field-block-label::before,.ui-ref8443 .required-label::before{content:'* ';color:#ba1a1a}
.ui-ref8443 .ref-input,.ui-ref8443 .ref-textarea{width:100%;border:0;border-radius:8px;background:#f2f4f8;color:#191c1f;padding:12px;font-size:14px;box-sizing:border-box}
.ui-ref8443 .ref-input{height:48px;display:flex;align-items:center;line-height:24px}
.ui-ref8443 .ref-textarea{min-height:90px;line-height:1.6}
.ui-ref8443 .counter{height:48px;display:grid;grid-template-columns:44px 1fr 44px;align-items:center;gap:8px;padding:6px 8px;border-radius:8px;background:#f2f4f8}
.ui-ref8443 .counter-btn{height:36px;border-radius:8px;background:#fff;box-shadow:0 1px 1px rgba(0,0,0,.05);font-size:20px;display:flex;align-items:center;justify-content:center}
.ui-ref8443 .counter-val{text-align:center;color:#999;font-family:'Plus Jakarta Sans:SemiBold',sans-serif;font-size:18px}
.ui-ref8443 .toggle-row{display:flex;gap:8px}
.ui-ref8443 .toggle-btn{flex:1;min-height:44px;border-radius:8px;background:#eceef2;color:#424655;font-size:14px;display:flex;align-items:center;justify-content:center}
.ui-ref8443 .toggle-btn.selected{background:#004fd0;color:#fff;font-family:'Noto Sans SC:Medium','Noto Sans SC',sans-serif}
.ui-ref8443 .choice-label{display:flex;justify-content:space-between;margin-bottom:6px}
.ui-ref8443 .choice-label b{font-family:'Noto Sans SC:Medium','Noto Sans SC',sans-serif;font-size:14px;font-weight:500}
.ui-ref8443 .choice-label span{color:#737686;font-size:10px}
.ui-ref8443 .section-title{display:flex;align-items:center;gap:8px;margin:0 0 10px;font-family:'Noto Sans SC:Medium','Noto Sans SC',sans-serif;font-size:16px;font-weight:500}
.ui-ref8443 .section-title i{width:4px;height:16px;border-radius:2px;background:#004fd0;flex:none}
.ui-ref8443 .range-labels{display:flex;justify-content:space-between;margin-top:8px;font-size:11px;color:#737686}
.ui-ref8443 .range-labels .active{color:#004fd0;font-family:'Noto Sans SC:Medium','Noto Sans SC',sans-serif}
.ui-ref8443 input.range{width:100%;accent-color:#004fd0}
.ui-ref8443 .hint{margin:-4px 0 10px;color:#737686;font-size:11px;line-height:1.5;display:block}
.ui-ref8443 .card h3{margin:0 0 10px;font-family:'Noto Sans SC:Medium','Noto Sans SC',sans-serif;font-size:16px;font-weight:500}
.ui-ref8443 .card h3 small,.ui-ref8443 .required-label small{color:#737686;font-size:10px;font-weight:400}
.ui-ref8443 .uploads{display:flex;gap:8px;overflow-x:auto}
.ui-ref8443 .upload-photo{position:relative;flex:0 0 104px;width:104px;height:104px;border-radius:8px;overflow:hidden;background:#eceef2}
.ui-ref8443 .upload-photo-image{width:100%;height:100%;object-fit:cover}
.ui-ref8443 .upload-caption{position:absolute;left:0;right:0;bottom:0;padding:6px;color:#fff;font-size:11px;text-align:center;background:linear-gradient(transparent,rgba(0,0,0,.75))}
.ui-ref8443 .sticky-filters{display:flex;flex-direction:column;gap:12px;margin-bottom:12px}
.ui-ref8443 .tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;padding:4px;border-radius:12px;background:#eceef2}
.ui-ref8443 .tab-btn{border-radius:8px;background:transparent;padding:8px 4px;color:#424655;font-size:13px;text-align:center;display:flex;align-items:center;justify-content:center}
.ui-ref8443 .tab-btn.active{background:#fff;color:#004fd0;box-shadow:0 1px 1px rgba(0,0,0,.05)}
.ui-ref8443 .chips{display:flex;gap:8px;overflow-x:auto}
.ui-ref8443 .chip-btn{flex:none;border-radius:999px;background:#e0e2e6;color:#424655;padding:4px 12px;font-size:11px;white-space:nowrap}
.ui-ref8443 .chip-btn.active{background:#004fd0;color:#fff}
.ui-ref8443 .work-top{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}
.ui-ref8443 .work-top small{color:#737686;font-size:10px;letter-spacing:.15px;flex:1}
.ui-ref8443 .work-card h2{margin:5px 0 8px;font-family:'Noto Sans SC:Medium','Noto Sans SC',sans-serif;font-size:17px;line-height:1.45;font-weight:500}
.ui-ref8443 .status{flex:none;padding:3px 8px;border-radius:999px;background:#fff4e6;color:#fe9c2d;font-size:11px}
.ui-ref8443 .urgency{display:inline;margin-right:6px;padding:2px 7px;border-radius:5px;background:#ba1a1a;color:#fff;font-size:11px}
.ui-ref8443 .urgency.orange{background:#fe9c2d}
.ui-ref8443 .meta{margin:0;color:#424655;font-size:13px}
.ui-ref8443 .work-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}
.ui-ref8443 .danger-card{border-left:4px solid #ba1a1a}
.ui-ref8443 .orange-card{border-left:4px solid #fe9c2d}
.ui-ref8443 .level-row{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.ui-ref8443 .level-btn{height:48px;border-radius:8px;background:#f2f4f8;color:#424655;font-size:14px;display:flex;align-items:center;justify-content:center}
.ui-ref8443 .level-btn.active{background:#fe9c2d;color:#fff}
.ui-ref8443 .level-btn i{display:inline-block;width:8px;height:8px;margin-right:5px;border-radius:50%;background:currentColor}
.ui-ref8443 .ref8443-action-bar{position:fixed;z-index:20;bottom:0;left:0;right:0;margin:0 auto;max-width:760px;padding:12px 16px calc(12px + env(safe-area-inset-bottom));background:rgba(255,255,255,.96);backdrop-filter:blur(12px);display:flex;gap:10px;box-shadow:0 -4px 16px rgba(0,0,0,.06)}
.ui-ref8443 .btn{flex:1;min-height:48px;border-radius:8px;font-size:16px;display:flex;align-items:center;justify-content:center}
.ui-ref8443 .btn.primary{background:#004fd0;color:#fff}
.ui-ref8443 .btn.secondary{flex:0 0 110px;background:#fff;color:#191c1f;border:1px solid #d7dae0}
.ui-ref8443 .btn.danger{background:#ba1a1a;color:#fff}
.ui-ref8443 .btn.orange{background:#fe9c2d;color:#fff;border-radius:12px;font-weight:700}
.ui-ref8443 .floating-rescue{position:fixed;z-index:12;right:16px;bottom:84px;background:#fe9c2d;color:#fff;border-radius:99px;padding:10px 16px;font-size:16px;box-shadow:0 6px 18px rgba(254,156,45,.33)}
.ui-ref8443 .req{color:#ba1a1a}

